// Generated by scripts/build-workflow.ts. Edit src/rules/rules.ts, not this node.
const RULES_VERSION = 'r1';
const LINK = /https?:\/\/\S+/gi;
const JUNK_TERMS = /\b(casino|crypto|bitcoin|viagra|payday|forex|betting|followers)\b/i;
const NEW_WORK = /\b(new (site|space|location|building|project)|second location|another location|additional (site|location|building)|quote|bid)\b/i;
const OUTAGE = /\b(down|no (heat|cooling|ac|a\/c|air)|not (cooling|heating|working)|out again|tripped|won'?t (start|fire|run))\b/i;
const HOME = /\b(my|our) (house|home)\b(?! office)|\bbedroom\b|\bsingle[- ]family\b/i;
function emailDomain(email) {
    return String(email ?? '').toLowerCase().split('@')[1] ?? '';
}
function sortLead(form, cfg) {
    const message = String(form.message ?? '');
    const links = message.match(LINK) ?? [];
    const state = String(form.property_state ?? '').trim().toUpperCase();
    const city = String(form.property_city ?? '').trim().toLowerCase();
    const domain = emailDomain(form.email);
    if (String(form.hp_field ?? '').trim() !== '') {
        return {
            rule_id: 'honeypot',
            category: 'spam',
            priority: 'low',
            reason: 'Hidden form field was filled in.',
            skip_crm: true
        };
    }
    if (cfg.disposable_email_domains.includes(domain)) {
        return {
            rule_id: 'disposable_email',
            category: 'spam',
            priority: 'low',
            reason: 'Throwaway email domain.',
            skip_crm: true
        };
    }
    if (links.length >= 3) {
        return {
            rule_id: 'link_stuffed',
            category: 'spam',
            priority: 'low',
            reason: 'Three or more links in the message.',
            skip_crm: false
        };
    }
    if (JUNK_TERMS.test(message) && links.length >= 1) {
        return {
            rule_id: 'junk_terms_with_link',
            category: 'spam',
            priority: 'low',
            reason: 'Junk terms alongside a link.',
            skip_crm: false
        };
    }
    if (form.inquiry_type === 'careers') {
        return {
            rule_id: 'careers_dropdown',
            category: 'job_seeker',
            priority: 'low',
            reason: 'Chose Careers on the form.',
            skip_crm: false
        };
    }
    if (form.inquiry_type === 'vendor') {
        return {
            rule_id: 'vendor_dropdown',
            category: 'vendor_pitch',
            priority: 'low',
            reason: 'Chose Vendor on the form.',
            skip_crm: false
        };
    }
    if (state !== '' && !cfg.service_states.includes(state)) {
        return {
            rule_id: 'state_out_of_area',
            category: 'not_a_fit',
            priority: 'low',
            reason: `Property is in ${state}, outside the service area.`,
            skip_crm: false
        };
    }
    if (cfg.out_of_area_cities.includes(city)) {
        return {
            rule_id: 'city_out_of_area',
            category: 'not_a_fit',
            priority: 'low',
            reason: 'Property city is outside the service area.',
            skip_crm: false
        };
    }
    if (HOME.test(message)) {
        return {
            rule_id: 'residential_words',
            category: 'not_a_fit',
            priority: 'low',
            reason: 'Message describes a home.',
            skip_crm: false
        };
    }
    if (String(form.customer_number ?? '').trim() !== '' && form.inquiry_type === 'existing_service' && !NEW_WORK.test(message)) {
        return {
            rule_id: 'customer_number',
            category: 'existing_customer',
            priority: OUTAGE.test(message) ? 'high' : 'normal',
            reason: 'Customer number given, asking about existing service.',
            skip_crm: false
        };
    }
    return null;
}

const CONTACT_FIELDS = [
    'firstname',
    'lastname',
    'phone',
    'company',
    'jobtitle',
    'website',
    'city',
    'state',
    'message'
];
function contactProperties(form, synthetic) {
    const properties = {};
    const set = (name, value)=>{
        if (value) properties[name] = value;
    };
    set('firstname', form.first_name);
    set('lastname', form.last_name);
    set('phone', form.phone);
    set('company', form.company);
    set('jobtitle', form.job_title);
    set('website', form.website);
    set('city', form.property_city);
    set('state', form.property_state);
    set('message', form.message);
    if (synthetic) properties.ltl_synthetic = true;
    return properties;
}

const CONFIG = {
  "service_states": ["OH", "KY"],
  "out_of_area_cities": ["cleveland", "toledo", "akron", "youngstown", "louisville", "lexington"],
  "disposable_email_domains": ["tempinbox.example.net", "throwaway.example.org", "burnermail.example.net", "mailinator.com", "guerrillamail.com", "10minutemail.com"],
  "free_email_domains": ["freemail.example.net", "mailbox.example.net", "postbox.example.org", "gmail.com", "yahoo.com", "outlook.com", "hotmail.com", "icloud.com", "aol.com", "proton.me"]
};

const body = $json.body ?? $json;
const form = body.form;
const synthetic = body.synthetic === true;
const rule = sortLead(form, CONFIG);

return {
  json: {
    submission_key: body.submission_key,
    synthetic,
    form,
    rule,
    skip_crm: Boolean(rule && rule.skip_crm),
    contact_input: { idProperty: 'email', id: form.email, properties: contactProperties(form, synthetic) },
  },
};
